"""A harness gate cancelled by a newer push is followed, and nothing else is.

Covers ``MQC_CAS_UNI_115765`` to ``115767``, inventoried in
``docs/design/consumer_ci.md`` section 4 and designed in section 3.11.3.

A failure here is **not a model finding**, so the module carries no priority
marker.
"""

# ------------------------------------------------------------- cases in here
# Generated by `tools/refresh_case_summaries.py`.
#
# TestMQCHarnessFollow
#   115765  a_gate_a_newer_commit_cancelled_is_followed_to_its_verdict
#   115766  a_red_gate_or_one_cancelled_in_place_is_refused_unfollowed
#   115767  following_stops_after_three_replaced_commits
# ------------------------------------------------------------ end of cases

import allure
import pytest

from cmn.case_steps import step
from tests.cases.follow_support import (
    FIFTH,
    FIRST,
    FOURTH,
    SECOND,
    THIRD,
    cancelled,
    follow,
    passed,
)
from tools.harness_pin import Greenness

pytestmark = pytest.mark.unit


@allure.epic("AP-Model-QC")
@allure.feature("Harness pairing")
class TestMQCHarnessFollow:
    """Only a gate a newer push cancelled is followed."""

    def MQC_CAS_UNI_115765_a_gate_a_newer_commit_cancelled_is_followed_to_its_verdict(
        self,
    ) -> None:
        """A cancelled gate whose ref moved is followed, and the chain is recorded.

        Design: ``consumer_ci.md`` section 3.11.3.

        Returns:
            None
        """
        step(1, "wait on a gate a newer push cancelled, the newer commit's gate passing")
        commit, verdict, asked = follow([SECOND], {FIRST: cancelled(), SECOND: passed()})
        assert (commit, verdict.green, asked) == (SECOND, True, [FIRST, SECOND]), (
            f"the replaced commit was not followed: {commit}, {verdict}, {asked}"
        )

        step(2, "read what the verdict records about the follow")
        assert f"from {FIRST[:12]} to {SECOND[:12]}" in verdict.reason, verdict.reason

        step(3, "follow two replaced commits in a row")
        commit, verdict, _ = follow(
            [SECOND, THIRD], {FIRST: cancelled(), SECOND: cancelled(), THIRD: passed()}
        )
        assert commit == THIRD and verdict.green, f"{commit}: {verdict}"

    def MQC_CAS_UNI_115766_a_red_gate_or_one_cancelled_in_place_is_refused_unfollowed(
        self,
    ) -> None:
        """A red gate, and a cancelled one whose ref has not moved, are returned unfollowed.

        Design: ``consumer_ci.md`` section 3.11.3.

        Returns:
            None
        """
        red = Greenness(green=False, reason="gate concluded failure", conclusion="failure")

        step(1, "wait on a gate that concluded red, a newer commit available")
        commit, verdict, asked = follow([SECOND], {FIRST: red, SECOND: passed()})
        assert (commit, verdict, asked) == (FIRST, red, [FIRST]), (
            f"a red harness gate was followed past: {commit}, {verdict}, {asked}"
        )

        step(2, "wait on a cancelled gate whose ref still names the same commit")
        commit, verdict, asked = follow([FIRST], {FIRST: cancelled()})
        assert (commit, verdict.green, asked) == (FIRST, False, [FIRST]), (
            f"a gate cancelled in place was followed: {commit}, {verdict}, {asked}"
        )

    def MQC_CAS_UNI_115767_following_stops_after_three_replaced_commits(self) -> None:
        """A third follow is taken; a fourth is not, and the refusal names the chain.

        Design: ``consumer_ci.md`` section 3.11.3.

        Returns:
            None
        """
        step(1, "follow three replaced commits, the third follow's gate passing")
        commit, verdict, _ = follow(
            [SECOND, THIRD, FOURTH],
            {FIRST: cancelled(), SECOND: cancelled(), THIRD: cancelled(), FOURTH: passed()},
        )
        assert commit == FOURTH and verdict.green, f"the third follow was refused: {verdict}"

        step(2, "meet a fourth cancelled gate with a fifth commit available")
        commit, verdict, asked = follow(
            [SECOND, THIRD, FOURTH, FIFTH],
            {FIRST: cancelled(), SECOND: cancelled(), THIRD: cancelled(),
             FOURTH: cancelled(), FIFTH: passed()},
        )
        assert (commit, verdict.green, asked[-1]) == (FOURTH, False, FOURTH), (
            f"following went past three: {commit}, {verdict}, {asked}"
        )

        step(3, "read the refusal")
        assert "followed 3 times and the gate is still cancelled" in verdict.reason, (
            verdict.reason
        )
